 "content": "def transform(grid):
    # Connect marker pixels horizontally and vertically across their overall bounding box,
    # preserving the marker cells themselves.
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    marks = [(r,c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not marks:
        return [row[:] for row in grid]
    mr, xr = min(r for r,c in marks), max(r for r,c in marks)
    mc, xc = min(c for r,c in marks), max(c for r,c in marks)
    out = [row[:] for row in grid]
    fill = 2
    for r in range(mr, xr+1):
        if any(rr == r for rr,cc in marks):
            for c in range(mc, xc+1):
                if grid[r][c] == bg: out[r][c] = fill
    for c in range(mc, xc+1):
        if any(cc == c for rr,cc in marks):
            for r in range(mr, xr+1):
                if grid[r][c] == bg: out[r][c] = fill
    return out
