 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row: counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not marks: return [row[:] for row in grid]
    color = next((v for v in counts if v != bg), 2)
    r0, r1 = min(r for r,c in marks), max(r for r,c in marks)
    c0, c1 = min(c for r,c in marks), max(c for r,c in marks)
    out = [row[:] for row in grid]
    # Join horizontal runs at rows containing multiple marked cells.
    for r in range(r0, r1 + 1):
        cols = [c for rr,c in marks if rr == r]
        if len(cols) >= 2:
            for c in range(c0, c1 + 1):
                if grid[r][c] == bg: out[r][c] = color
    # Draw the two outer vertical rails of the marked area.
    for c in (c0, c1):
        for r in range(r0, r1 + 1):
            if grid[r][c] == bg: out[r][c] = color
    return out
