 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] != background]
    out = [row[:] for row in grid]
    if not points:
        return out
    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)

    # Close the bounding rectangle on its outermost rows and columns.
    for c in range(c0, c1 + 1):
        if grid[r0][c] == background:
            out[r0][c] = 2
        if grid[r1][c] == background:
            out[r1][c] = 2
    for r in range(r0, r1 + 1):
        if grid[r][c0] == background:
            out[r][c0] = 2
        if grid[r][c1] == background:
            out[r][c1] = 2

    # Fill horizontal gaps on interior rows containing at least four marks.
    for r in range(r0 + 1, r1):
        cols = [c for c in range(w) if grid[r][c] != background]
        if len(cols) >= 4:
            for c in range(min(cols), max(cols) + 1):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out
